// Good: Using unique IDs as keys
function TodoList({ todos }) {
  return (
    <ul>
      {todos.map(todo => (
        <li key={todo.id}>{todo.text}</li>
      ))}
    </ul>
  );
}

// Bad: Using array index as key
function TodoList({ todos }) {
  return (
    <ul>
      {todos.map((todo, index) => (
        <li key={index}>{todo.text}</li> // Problems if list changes
      ))}
    </ul>
  );
}

// When index is acceptable:
// - List is static (never changes)
// - Items have no IDs
// - List is never reordered/filtered

// Keys with components
function ListItem({ item }) {
  return <div>{item.name}</div>;
}

function List({ items }) {
  return (
    <ul>
      {items.map(item => (
        <ListItem key={item.id} item={item} />
      ))}
    </ul>
  );
}

// Keys help React:
// 1. Identify which items are new
// 2. Identify which items moved
// 3. Identify which items were removed
// 4. Preserve state of existing items
